-- ============================================================================
-- Price-Promo-Margin Analytics: Food Delivery Case Study
-- Engine: MySQL 8.0+ (window functions and recursive CTEs required)
-- Sections: 1 Schema | 2 Seed data | 3 Validation | 4 KPIs | 5 Reconciliation
--
-- NOTE: Section 2 loads SYNTHETIC demo data generated by formulas so the script
-- runs end to end. Replace it with your real CSVs (see 2e) before quoting
-- any result. COGS % values are analyst assumptions, not real cost data.
-- ============================================================================

CREATE DATABASE IF NOT EXISTS price_promo_margin;
USE price_promo_margin;

-- ----------------------------------------------------------------------------
-- 1. SCHEMA
-- ----------------------------------------------------------------------------
SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS fact_orders;
DROP TABLE IF EXISTS dim_meal;
DROP TABLE IF EXISTS dim_center;
DROP TABLE IF EXISTS dim_week;
DROP TABLE IF EXISTS dim_cogs_assumptions;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE dim_meal (
    meal_id   INT PRIMARY KEY,
    category  VARCHAR(30) NOT NULL,
    cuisine   VARCHAR(20) NOT NULL
);

CREATE TABLE dim_center (
    center_id    INT PRIMARY KEY,
    city_code    INT NOT NULL,
    region_code  INT NOT NULL,
    center_type  VARCHAR(10) NOT NULL,
    op_area      DECIMAL(4,1) NOT NULL
);

-- No real calendar dates in source data: weeks are modeled as a repeating
-- cycle for period/quarter rollups.
CREATE TABLE dim_week (
    week_number       INT PRIMARY KEY,
    cycle_year        INT NOT NULL,
    period_in_cycle   INT NOT NULL,
    quarter_in_cycle  INT NOT NULL
);

-- Assumption layer, kept separate so real cost data can replace it later
-- without touching the fact table.
CREATE TABLE dim_cogs_assumptions (
    category          VARCHAR(30) PRIMARY KEY,
    assumed_cogs_pct  DECIMAL(4,3) NOT NULL
);

CREATE TABLE fact_orders (
    order_id               BIGINT PRIMARY KEY,
    week_number            INT NOT NULL,
    center_id              INT NOT NULL,
    meal_id                INT NOT NULL,
    checkout_price         DECIMAL(8,2) NOT NULL,
    base_price             DECIMAL(8,2) NOT NULL,
    discount_amount        DECIMAL(8,2) NOT NULL,
    discount_pct           DECIMAL(6,4) NOT NULL,
    emailer_for_promotion  SMALLINT NOT NULL,
    homepage_featured      SMALLINT NOT NULL,
    promo_type             VARCHAR(15) NOT NULL,  -- None / Email Only / Homepage Only / Both
    num_orders             INT NOT NULL,
    revenue                DECIMAL(12,2) NOT NULL,
    FOREIGN KEY (week_number) REFERENCES dim_week(week_number),
    FOREIGN KEY (center_id)   REFERENCES dim_center(center_id),
    FOREIGN KEY (meal_id)     REFERENCES dim_meal(meal_id),
    INDEX idx_fact_meal   (meal_id),
    INDEX idx_fact_center (center_id),
    INDEX idx_fact_week   (week_number),
    INDEX idx_fact_promo  (promo_type)
);

-- ----------------------------------------------------------------------------
-- 2. SEED DATA (synthetic, deterministic)
-- ----------------------------------------------------------------------------
-- 2a. Dimensions
INSERT INTO dim_meal (meal_id, category, cuisine) VALUES
    (1, 'Beverages', 'Continental'),
    (2, 'Beverages', 'Indian'),
    (3, 'Pizza',     'Italian'),
    (4, 'Pizza',     'Continental'),
    (5, 'Biryani',   'Indian'),
    (6, 'Biryani',   'Indian'),
    (7, 'Salad',     'Continental'),
    (8, 'Salad',     'Thai');

INSERT INTO dim_center (center_id, city_code, region_code, center_type, op_area) VALUES
    (11, 590, 56, 'TYPE_A', 3.9),
    (12, 590, 56, 'TYPE_B', 4.5),
    (13, 456, 34, 'TYPE_A', 2.8),
    (14, 456, 34, 'TYPE_C', 5.1);

INSERT INTO dim_cogs_assumptions (category, assumed_cogs_pct) VALUES
    ('Beverages', 0.300),
    ('Pizza',     0.420),
    ('Biryani',   0.480),
    ('Salad',     0.380);

-- 2b. Weeks 1-26 (two 13-week quarters, 4-week periods)
INSERT INTO dim_week (week_number, cycle_year, period_in_cycle, quarter_in_cycle)
WITH RECURSIVE wk (n) AS (
    SELECT 1 UNION ALL SELECT n + 1 FROM wk WHERE n < 26
)
SELECT n, 1, CEIL(n / 4), CEIL(n / 13) FROM wk;

-- 2c. Fact table: every meal x center x week (8 x 4 x 26 = 832 rows).
--     Price, discount, promo flags and volume come from deterministic formulas;
--     discount and revenue columns are derived so internal checks tie out.
INSERT INTO fact_orders
    (order_id, week_number, center_id, meal_id, checkout_price, base_price,
     discount_amount, discount_pct, emailer_for_promotion, homepage_featured,
     promo_type, num_orders, revenue)
SELECT
    ROW_NUMBER() OVER (ORDER BY t.week_number, t.center_id, t.meal_id) AS order_id,
    t.week_number,
    t.center_id,
    t.meal_id,
    t.checkout_price,
    t.base_price,
    ROUND(t.base_price - t.checkout_price, 2)                          AS discount_amount,
    ROUND((t.base_price - t.checkout_price) / t.base_price, 4)         AS discount_pct,
    t.email,
    t.home,
    CASE WHEN t.email = 1 AND t.home = 1 THEN 'Both'
         WHEN t.email = 1                THEN 'Email Only'
         WHEN t.home  = 1                THEN 'Homepage Only'
         ELSE 'None' END                                               AS promo_type,
    t.num_orders,
    ROUND(t.checkout_price * t.num_orders, 2)                          AS revenue
FROM (
    SELECT
        s.*,
        ROUND(s.base_price * (1 - s.disc), 2)                          AS checkout_price,
        ROUND(s.vol * (1 + s.disc * 3 + s.email * 0.4 + s.home * 0.5)) AS num_orders
    FROM (
        SELECT
            w.week_number,
            c.center_id,
            m.meal_id,
            (100 + m.meal_id * 15 + (c.center_id - 10) * 2)            AS base_price,
            MOD(w.week_number * 7 + m.meal_id * 5 + c.center_id * 3, 6) * 0.05 AS disc,
            CASE WHEN MOD(w.week_number + m.meal_id, 3) = 0 THEN 1 ELSE 0 END  AS email,
            CASE WHEN MOD(w.week_number + c.center_id * 2 + m.meal_id, 4) = 0
                 THEN 1 ELSE 0 END                                              AS home,
            80 + MOD(m.meal_id * 37 + c.center_id * 11 + w.week_number * 13, 60) AS vol
        FROM dim_week w
        CROSS JOIN dim_center c
        CROSS JOIN dim_meal m
    ) s
) t;

-- 2d. Quick load check (expected: fact 832, meal 8, center 4, week 26, cogs 4)
SELECT 'fact_orders' AS table_name, COUNT(*) AS total_rows FROM fact_orders
UNION ALL SELECT 'dim_meal', COUNT(*) FROM dim_meal
UNION ALL SELECT 'dim_center', COUNT(*) FROM dim_center
UNION ALL SELECT 'dim_week', COUNT(*) FROM dim_week
UNION ALL SELECT 'dim_cogs_assumptions', COUNT(*) FROM dim_cogs_assumptions;

-- 2e. TO USE YOUR REAL DATA: skip 2a-2c and load CSVs instead
--     (dimensions first, fact table last because of foreign keys).
--     Requires local_infile enabled; adjust paths.
--   LOAD DATA LOCAL INFILE 'dim_meal.csv' INTO TABLE dim_meal
--       FIELDS TERMINATED BY ',' IGNORE 1 LINES;
--   (repeat for dim_center, dim_week, dim_cogs_assumptions, then fact_orders)

-- ----------------------------------------------------------------------------
-- 3. DATA VALIDATION (every query below should return 0 rows or 0 counts)
-- ----------------------------------------------------------------------------
-- 3a. Nulls (NOT NULL constraints already block most; kept as a visible check)
SELECT
    COUNT(*) AS total_records,
    SUM(order_id       IS NULL) AS missing_order_ids,
    SUM(week_number    IS NULL) AS missing_week_numbers,
    SUM(center_id      IS NULL) AS missing_center_ids,
    SUM(meal_id        IS NULL) AS missing_meal_ids,
    SUM(checkout_price IS NULL) AS missing_checkout_prices,
    SUM(base_price     IS NULL) AS missing_base_prices,
    SUM(num_orders     IS NULL) AS missing_order_quantities,
    SUM(revenue        IS NULL) AS missing_revenue
FROM fact_orders;

-- 3b. Duplicate order_id
SELECT order_id, COUNT(*) AS duplicate_count
FROM fact_orders
GROUP BY order_id
HAVING COUNT(*) > 1;

-- 3c. Negative values
SELECT * FROM fact_orders
WHERE checkout_price < 0 OR base_price < 0 OR discount_amount < 0
   OR num_orders < 0 OR revenue < 0;

-- 3d. Discount % outside 0-1 (markups treated as invalid; the discount bands
--     in section 4 are consistent with this rule)
SELECT * FROM fact_orders
WHERE discount_pct < 0 OR discount_pct > 1;

-- 3e. Flag columns must be 0/1
SELECT * FROM fact_orders
WHERE emailer_for_promotion NOT IN (0, 1) OR homepage_featured NOT IN (0, 1);

-- 3f. promo_type must agree with the two flags
SELECT * FROM fact_orders
WHERE promo_type <> CASE
        WHEN emailer_for_promotion = 1 AND homepage_featured = 1 THEN 'Both'
        WHEN emailer_for_promotion = 1 THEN 'Email Only'
        WHEN homepage_featured = 1 THEN 'Homepage Only'
        ELSE 'None' END;

-- 3g. Orphan keys (fact rows with no matching dimension row)
SELECT f.* FROM fact_orders f
LEFT JOIN dim_meal m   ON f.meal_id = m.meal_id     WHERE m.meal_id IS NULL;
SELECT f.* FROM fact_orders f
LEFT JOIN dim_center c ON f.center_id = c.center_id WHERE c.center_id IS NULL;
SELECT f.* FROM fact_orders f
LEFT JOIN dim_week w   ON f.week_number = w.week_number WHERE w.week_number IS NULL;

-- 3h. Price recalculation: discount_amount and discount_pct vs base/checkout
SELECT order_id, base_price, checkout_price, discount_amount, discount_pct
FROM fact_orders
WHERE ABS((base_price - checkout_price) - discount_amount) > 0.01
   OR ABS((base_price - checkout_price) / NULLIF(base_price, 0) - discount_pct) > 0.0001;

-- 3i. Revenue recalculation: checkout_price * num_orders vs revenue
SELECT order_id, checkout_price, num_orders, revenue,
       checkout_price * num_orders AS calculated_revenue,
       revenue - (checkout_price * num_orders) AS revenue_difference
FROM fact_orders
WHERE ABS(revenue - (checkout_price * num_orders)) > 0.05;

-- 3j. COGS assumptions: valid range and full category coverage
SELECT category, assumed_cogs_pct FROM dim_cogs_assumptions
WHERE assumed_cogs_pct < 0 OR assumed_cogs_pct > 1 OR assumed_cogs_pct IS NULL;

SELECT DISTINCT m.category
FROM dim_meal m
LEFT JOIN dim_cogs_assumptions c ON m.category = c.category
WHERE c.category IS NULL;

-- ----------------------------------------------------------------------------
-- 4. CORE KPI QUERIES
-- ----------------------------------------------------------------------------
-- 4a. Headline KPIs
SELECT
    COUNT(*)                                  AS total_records,
    SUM(num_orders)                           AS total_units,
    ROUND(SUM(revenue), 2)                    AS total_revenue,
    ROUND(SUM(revenue) / NULLIF(SUM(num_orders), 0), 2) AS revenue_per_unit,
    ROUND(AVG(discount_pct) * 100, 2)         AS simple_avg_discount_pct,
    -- revenue-weighted view: discount given up as a share of list-price sales
    ROUND(100.0 * SUM(discount_amount * num_orders)
          / NULLIF(SUM(base_price * num_orders), 0), 2) AS weighted_discount_pct
FROM fact_orders;

-- 4b. Revenue contribution by category
SELECT
    m.category,
    SUM(f.num_orders)              AS total_units,
    ROUND(SUM(f.revenue), 2)       AS total_revenue,
    ROUND(100.0 * SUM(f.revenue) / NULLIF((SELECT SUM(revenue) FROM fact_orders), 0), 2)
                                   AS revenue_contribution_pct,
    RANK() OVER (ORDER BY SUM(f.revenue) DESC) AS revenue_rank
FROM fact_orders f
JOIN dim_meal m ON f.meal_id = m.meal_id
GROUP BY m.category
ORDER BY revenue_rank;

-- 4c. Promo performance by channel combination.
--     Compares AVERAGE units per record vs non-promoted records (association /
--     uplift, NOT proven incrementality: promoted meals may already be popular).
SELECT
    f.promo_type,
    COUNT(*)                            AS order_records,
    SUM(f.num_orders)                   AS total_units,
    ROUND(AVG(f.num_orders), 2)         AS avg_units_per_record,
    ROUND(SUM(f.revenue), 2)            AS total_revenue,
    ROUND(AVG(f.checkout_price), 2)     AS avg_checkout_price,
    ROUND(AVG(f.num_orders)
          / NULLIF(MAX(b.base_avg), 0) - 1, 4) AS uplift_vs_non_promoted
FROM fact_orders f
CROSS JOIN (SELECT AVG(num_orders) AS base_avg
            FROM fact_orders WHERE promo_type = 'None') b
GROUP BY f.promo_type
ORDER BY total_revenue DESC;

-- 4d. Promo performance within category
SELECT
    m.category,
    f.promo_type,
    COUNT(*)                        AS order_records,
    SUM(f.num_orders)               AS total_units,
    ROUND(AVG(f.num_orders), 2)     AS avg_units_per_record,
    ROUND(SUM(f.revenue), 2)        AS total_revenue
FROM fact_orders f
JOIN dim_meal m ON f.meal_id = m.meal_id
GROUP BY m.category, f.promo_type
ORDER BY m.category, total_revenue DESC;

-- 4e. Discount depth vs volume (directional relationship only; discounts are
--     confounded by promos. A proper elasticity needs a log-log regression
--     controlling for promo type.)
SELECT
    m.category,
    CASE WHEN f.discount_pct <= 0    THEN '0. No discount'
         WHEN f.discount_pct <= 0.10 THEN '1. Up to 10%'
         WHEN f.discount_pct <= 0.20 THEN '2. 10-20%'
         WHEN f.discount_pct <= 0.30 THEN '3. 20-30%'
         ELSE '4. Above 30%' END AS discount_band,
    COUNT(*)                        AS order_records,
    ROUND(AVG(f.num_orders), 2)     AS avg_units_per_record,
    ROUND(SUM(f.revenue), 2)        AS total_revenue
FROM fact_orders f
JOIN dim_meal m ON f.meal_id = m.meal_id
GROUP BY m.category, discount_band
ORDER BY m.category, discount_band;

-- 4f. Margin by category (assumption-based COGS)
SELECT
    m.category,
    ROUND(SUM(f.revenue), 2)                                  AS total_revenue,
    ROUND(SUM(f.revenue * c.assumed_cogs_pct), 2)             AS estimated_cogs,
    ROUND(SUM(f.revenue * (1 - c.assumed_cogs_pct)), 2)       AS estimated_gross_profit,
    ROUND(100.0 * SUM(f.revenue * (1 - c.assumed_cogs_pct))
          / NULLIF(SUM(f.revenue), 0), 2)                     AS estimated_gross_margin_pct
FROM fact_orders f
JOIN dim_meal m ON f.meal_id = m.meal_id
JOIN dim_cogs_assumptions c ON m.category = c.category
GROUP BY m.category
ORDER BY estimated_gross_profit DESC;

-- 4g. Margin by promo type
SELECT
    f.promo_type,
    ROUND(SUM(f.revenue), 2)                                  AS total_revenue,
    ROUND(SUM(f.revenue * (1 - c.assumed_cogs_pct)), 2)       AS estimated_gross_profit,
    ROUND(100.0 * SUM(f.revenue * (1 - c.assumed_cogs_pct))
          / NULLIF(SUM(f.revenue), 0), 2)                     AS estimated_gross_margin_pct
FROM fact_orders f
JOIN dim_meal m ON f.meal_id = m.meal_id
JOIN dim_cogs_assumptions c ON m.category = c.category
GROUP BY f.promo_type
ORDER BY estimated_gross_profit DESC;

-- 4h. Center profitability by type and region
SELECT
    dc.center_type,
    dc.region_code,
    COUNT(DISTINCT dc.center_id)                              AS total_centres,
    ROUND(SUM(f.revenue), 2)                                  AS total_revenue,
    ROUND(SUM(f.revenue * (1 - c.assumed_cogs_pct)), 2)       AS estimated_gross_profit,
    ROUND(100.0 * SUM(f.revenue * (1 - c.assumed_cogs_pct))
          / NULLIF(SUM(f.revenue), 0), 2)                     AS estimated_gross_margin_pct
FROM fact_orders f
JOIN dim_center dc ON f.center_id = dc.center_id
JOIN dim_meal m ON f.meal_id = m.meal_id
JOIN dim_cogs_assumptions c ON m.category = c.category
GROUP BY dc.center_type, dc.region_code
ORDER BY estimated_gross_profit DESC;

-- 4i. Center rank within center_type
WITH center_revenue AS (
    SELECT dc.center_id, dc.center_type, dc.region_code, SUM(f.revenue) AS total_revenue
    FROM fact_orders f
    JOIN dim_center dc ON f.center_id = dc.center_id
    GROUP BY dc.center_id, dc.center_type, dc.region_code
)
SELECT center_id, center_type, region_code,
       ROUND(total_revenue, 2) AS total_revenue,
       DENSE_RANK() OVER (PARTITION BY center_type ORDER BY total_revenue DESC) AS centre_rank
FROM center_revenue
ORDER BY center_type, centre_rank;

-- 4j. Week-over-week revenue growth
WITH weekly_revenue AS (
    SELECT week_number, SUM(revenue) AS total_revenue
    FROM fact_orders
    GROUP BY week_number
),
revenue_comparison AS (
    SELECT week_number, total_revenue,
           LAG(total_revenue) OVER (ORDER BY week_number) AS previous_week_revenue
    FROM weekly_revenue
)
SELECT
    week_number,
    ROUND(total_revenue, 2)                                   AS current_week_revenue,
    ROUND(previous_week_revenue, 2)                           AS previous_week_revenue,
    ROUND(total_revenue - previous_week_revenue, 2)           AS revenue_change,
    ROUND(100.0 * (total_revenue - previous_week_revenue)
          / NULLIF(previous_week_revenue, 0), 2)              AS revenue_growth_pct
FROM revenue_comparison
ORDER BY week_number;

-- 4k. Price / volume decomposition by category, week over week.
--     At category level the leftover is the interaction term
--     (delta price x delta units), NOT true mix. True mix needs meal-level data.
WITH weekly_category AS (
    SELECT m.category, f.week_number,
           SUM(f.num_orders) AS units,
           SUM(f.revenue)    AS revenue,
           SUM(f.revenue) / NULLIF(SUM(f.num_orders), 0) AS avg_price
    FROM fact_orders f
    JOIN dim_meal m ON f.meal_id = m.meal_id
    GROUP BY m.category, f.week_number
),
with_prior AS (
    SELECT *,
           LAG(units)     OVER (PARTITION BY category ORDER BY week_number) AS prior_units,
           LAG(avg_price) OVER (PARTITION BY category ORDER BY week_number) AS prior_avg_price,
           LAG(revenue)   OVER (PARTITION BY category ORDER BY week_number) AS prior_revenue
    FROM weekly_category
)
SELECT
    category,
    week_number,
    ROUND(revenue - prior_revenue, 2)                         AS revenue_change,
    ROUND((avg_price - prior_avg_price) * prior_units, 2)     AS price_effect,
    ROUND((units - prior_units) * prior_avg_price, 2)         AS volume_effect,
    ROUND((avg_price - prior_avg_price) * (units - prior_units), 2) AS interaction_effect
FROM with_prior
WHERE prior_units IS NOT NULL
ORDER BY category, week_number;

-- 4l. Categories with below-average margin. Uses a REVENUE-WEIGHTED benchmark,
--     not a simple average of category percentages.
WITH category_metrics AS (
    SELECT m.category,
           SUM(f.revenue) AS total_revenue,
           SUM(f.revenue * (1 - c.assumed_cogs_pct)) AS gross_profit
    FROM fact_orders f
    JOIN dim_meal m ON f.meal_id = m.meal_id
    JOIN dim_cogs_assumptions c ON m.category = c.category
    GROUP BY m.category
)
SELECT category,
       ROUND(total_revenue, 2) AS total_revenue,
       ROUND(gross_profit, 2)  AS estimated_gross_profit,
       ROUND(100.0 * gross_profit / total_revenue, 2) AS margin_pct
FROM category_metrics
WHERE gross_profit / total_revenue <
      (SELECT SUM(gross_profit) / SUM(total_revenue) FROM category_metrics)
ORDER BY total_revenue DESC;

-- ----------------------------------------------------------------------------
-- 5. RECONCILIATION (each pair of numbers must match)
-- ----------------------------------------------------------------------------
-- 5a. Total revenue: fact table vs sum of category totals vs sum of promo totals
SELECT
    (SELECT ROUND(SUM(revenue), 2) FROM fact_orders) AS fact_total,
    (SELECT ROUND(SUM(rev), 2) FROM (
        SELECT SUM(f.revenue) AS rev
        FROM fact_orders f JOIN dim_meal m ON f.meal_id = m.meal_id
        GROUP BY m.category) x)                       AS category_total,
    (SELECT ROUND(SUM(rev), 2) FROM (
        SELECT SUM(revenue) AS rev FROM fact_orders GROUP BY promo_type) y)
                                                      AS promo_total;

-- 5b. Gross profit: category roll-up vs row-level calculation
SELECT ROUND(SUM(f.revenue * (1 - c.assumed_cogs_pct)), 2) AS total_estimated_gross_profit
FROM fact_orders f
JOIN dim_meal m ON f.meal_id = m.meal_id
JOIN dim_cogs_assumptions c ON m.category = c.category;

-- 5c. Week coverage
SELECT MIN(week_number) AS first_week, MAX(week_number) AS last_week,
       COUNT(*) AS weeks_in_dimension
FROM dim_week;
